import sys, json

class Sim:
    def __init__(self, inp):
        self.inp=inp
        self.n=inp["n"]; self.cap=inp["capacity"]; self.edges=inp["edges"]; self.rounds=inp["rounds"]
        E=len(self.edges); self.E=E
        self.U=[e["u"] for e in self.edges]; self.V=[e["v"] for e in self.edges]
        self.P=[e["ping_us"] for e in self.edges]; self.A=[e["ack_us"] for e in self.edges]
        self.L=[e["label"] for e in self.edges]
        self.out=[[] for _ in range(self.n)]
        for i in range(E): self.out[self.U[i]].append(i)
        R=len(self.rounds); self.R=R
        self.launch=[r["launch_us"] for r in self.rounds]
        self.deadline=[r["launch_us"]+r["timeout_us"] for r in self.rounds]
        self.hdel=[r["host_delay_us"] for r in self.rounds]
        self.dropH=[r["drop_host_ack"] for r in self.rounds]
        self.dropP=[set(r["drop_ping"]) for r in self.rounds]
        self.dropA=[set(r["drop_ack"]) for r in self.rounds]
        self.evs=[]; self.order=0
        self.ent={}; self.ncount=[0]*self.n; self.cpeak=[0]*self.n
        self.tot=0; self.peak=0
        self.met=dict(host_probe_tx=R,network_ping_tx=0,network_ack_tx=0,host_ack_tx=0,
                      deduplicated_ping=0,capacity_drops=0,late_ping=0,ignored_ack=0,allocations=0)
        self.sstarted=[False]*R; self.sfin=[None]*R; self.scomp=[None]*R
        self.hdeliv=[None]*R; self.sproof=[None]*R
    def add(self,t,pri,r,key,kind,data):
        self.evs.append((t,pri,r,key,self.order,kind,data)); self.order+=1
    def ack_tx(self,edge,proof,comp,t,r):
        self.met['network_ack_tx']+=1
        if edge not in self.dropA[r]:
            self.add(t+self.A[edge],3,r,edge,'ack',(edge,proof,comp))
    def finalize(self,e,comp,t):
        if e['fin']: return
        e['fin']=True; e['comp']=comp; e['cp']=frozenset(e['proof']); e['cc']=comp
        r=e['r']; node=e['node']
        for pe in sorted(e['wp']):
            self.ack_tx(pe,e['cp'],comp,t,r)
        if node==0:
            self.sfin[r]=t; self.scomp[r]=comp; self.sproof[r]=e['cp']
            self.met['host_ack_tx']+=1
            if not self.dropH[r]:
                self.add(t+self.hdel[r],5,r,-1,'hostack',None)
    def alloc(self,r,node,t,parent):
        self.met['allocations']+=1
        e={'r':r,'node':node,'proof':set(),'fin':False,'comp':None,
           'oe':self.out[node],'exp':len(self.out[node]),'cred':{},'wp':set(),
           'cp':frozenset(),'cc':False}
        self.ent[(r,node)]=e
        self.ncount[node]+=1; self.tot+=1
        if self.ncount[node]>self.cpeak[node]: self.cpeak[node]=self.ncount[node]
        if self.tot>self.peak: self.peak=self.tot
        if parent is not None: e['wp'].add(parent)
        self.add(self.deadline[r],4,r,node,'timeout',node)
        for edge in self.out[node]:
            self.met['network_ping_tx']+=1
            if edge not in self.dropP[r]:
                self.add(t+self.P[edge],2,r,edge,'ping',edge)
        if e['exp']==0:
            self.finalize(e,True,t)
        return e
    def run(self):
        for r in range(self.R):
            self.add(self.launch[r],2,r,-1,'host',None)
            self.add(self.deadline[r]+1,1,r,-1,'rel',None)
        last=0
        while self.evs:
            self.evs.sort(key=lambda x:(x[0],x[1],x[2],x[3],x[4]))
            t,pri,r,key,o,kind,data=self.evs.pop(0)
            last=t
            if kind=='rel':
                for node in range(self.n):
                    if (r,node) in self.ent:
                        del self.ent[(r,node)]; self.ncount[node]-=1; self.tot-=1
            elif kind=='host':
                if self.ncount[0]>=self.cap[0]:
                    self.met['capacity_drops']+=1
                else:
                    self.sstarted[r]=True
                    self.alloc(r,0,t,None)
            elif kind=='ping':
                edge=data; v=self.V[edge]
                if t>self.deadline[r]:
                    self.met['late_ping']+=1
                else:
                    e=self.ent.get((r,v))
                    if e is not None:
                        self.met['deduplicated_ping']+=1
                        e['wp'].add(edge)
                        if e['fin']:
                            self.ack_tx(edge,e['cp'],e['cc'],t,r)
                    else:
                        if self.ncount[v]>=self.cap[v]:
                            self.met['capacity_drops']+=1
                        else:
                            self.alloc(r,v,t,edge)
            elif kind=='ack':
                edge,proof,comp=data; u=self.U[edge]
                e=self.ent.get((r,u))
                if e is None or e['fin'] or edge in e['cred']:
                    self.met['ignored_ack']+=1
                else:
                    e['cred'][edge]=comp; e['proof'].add(edge); e['proof']|=proof
                    if len(e['cred'])==e['exp']:
                        self.finalize(e,all(e['cred'].values()),t)
            elif kind=='timeout':
                node=data; e=self.ent.get((r,node))
                if e is not None and not e['fin']:
                    self.finalize(e,False,t)
            elif kind=='hostack':
                self.hdeliv[r]=t
        end=last if self.R>0 else 0
        self.met['cache_peak']=self.cpeak; self.met['peak_entries']=self.peak; self.met['end_us']=end
        return self.build()
    def build(self):
        # paths
        n=self.n; E=self.E
        adj=[[] for _ in range(n)]; radj=[[] for _ in range(n)]
        for i in range(E): adj[self.U[i]].append(i); radj[self.V[i]].append(i)
        reach=[False]*n; st=[0]; reach[0]=True
        while st:
            x=st.pop()
            for e in adj[x]:
                y=self.V[e]
                if not reach[y]: reach[y]=True; st.append(y)
        cane=[False]*n; cane[n-1]=True; st=[n-1]
        while st:
            x=st.pop()
            for e in radj[x]:
                y=self.U[e]
                if not cane[y]: cane[y]=True; st.append(y)
        rel=[[] for _ in range(n)]
        for i in range(E):
            if reach[self.U[i]] and cane[self.V[i]]: rel[self.U[i]].append(i)
        paths=[]; cur=[]
        def dfs(x):
            if x==n-1:
                paths.append(tuple(cur)); return
            for e in rel[x]:
                cur.append(e); dfs(self.V[e]); cur.pop()
        if cane[0]: dfs(0)
        sigs=[tuple(self.L[e] for e in p) for p in paths]
        pset=[frozenset(p) for p in paths]
        from collections import defaultdict
        bysig=defaultdict(list)
        for i,s in enumerate(sigs): bysig[s].append(i)
        evid={s:set() for s in bysig}
        for r in range(self.R):
            if self.hdeliv[r] is None: continue
            S=set(self.sproof[r])
            obs=set()
            for i in range(len(paths)):
                if pset[i].issubset(S): obs.add(sigs[i])
            for s in obs:
                if s in evid: evid[s].add(r)
        classes=[]
        for s in sorted(bysig):
            idxs=bysig[s]; cnt=len(idxs)
            if cnt==1: w=[list(paths[idxs[0]])]
            else: w=[list(paths[idxs[0]]),list(paths[idxs[1]])]
            ev=sorted(evid[s])
            state='unobserved' if not ev else ('unique' if cnt==1 else 'ambiguous')
            classes.append({'signature':list(s),'candidate_count':cnt,'evidence_rounds':ev,'state':state,'candidate_witnesses':w})
        ob=len(classes); obsv=sum(1 for c in classes if c['evidence_rounds'])
        uo=sum(1 for c in classes if c['evidence_rounds'] and c['candidate_count']==1)
        ao=sum(1 for c in classes if c['evidence_rounds'] and c['candidate_count']!=1)
        upper=sum(c['candidate_count'] for c in classes if c['evidence_rounds'])
        if ob==0: cov='no-routes'
        elif obsv==0: cov='no-evidence'
        elif obsv==ob: cov='complete'
        else: cov='partial'
        summary={'topology_paths':len(paths),'observable_classes':ob,'observed_classes':obsv,
                 'unique_observed_classes':uo,'ambiguous_observed_classes':ao,
                 'path_evidence_lower':obsv,'path_evidence_upper':upper,'coverage_status':cov}
        rounds_out=[]
        for r in range(self.R):
            started=self.sstarted[r]; sp=self.sproof[r]
            rounds_out.append({'id':r,'started':bool(started),
                'source_final_us':self.sfin[r] if started else None,
                'source_complete':self.scomp[r] if started else None,
                'host_delivery_us':self.hdeliv[r],
                'source_proof':sorted(sp) if sp is not None else []})
        return {'rounds':rounds_out,'metrics':self.met,'classes':classes,'summary':summary}

if __name__=='__main__':
    print(json.dumps(Sim(json.load(sys.stdin)).run()))
